definition.script:
pipeline {
    agent {label 'agent-1'}
    tools
    {
        maven 'Maven3.9'
        jdk 'jdk17'
    }
    parameters{
        string(name: 'BRANCH_NAME' ,defaultvalue = 'main' ,description = 'Git branch to build')
    }
 stages {
        stage('Git checkout') {
            steps {
                git branch: "${params.BRANCH_NAME}", url: 'https://github.com/krishant590/Boardgame-main-Working.git'
            }
        }
                stage('Build') {
            steps {
                 sh 'mvn package'
            }
        }
    }
}
